  const inv2 = createIssuedInvoice('C-001', '2024-03-16', 1);

  const result = vatSummary([inv1, inv2]);

  assert.ok(result.length > 0);
  // Both invoices have DEV-HOUR (9500 cents each), bases aggregate
  const entry = result[0];
  assert.ok(entry.base > 9500); // Should be greater than single invoice
});

test('vatSummary with multiple SKUs in single invoice', () => {
