test('vatSummary calculates base correctly without discounts', () => {
  const invoice = createIssuedInvoice('C-001', '2024-03-15', 2);
  const result = vatSummary([invoice]);

  assert.ok(result.length > 0);
  // Base should be qty * unitPrice (DEV-HOUR = 9500 cents)
  // 2 * 9500 = 19000, possibly with tier discount applied
  assert.ok(result[0].base > 0);
  assert.ok(result[0].base <= 2 * 9500);
});

test('vatSummary calculates base correctly with line discount', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 2, discountPercent: 10 }],
  });
  if (!result.ok) throw new Error(`createInvoice failed: ${result.error}`);

  const issued = issueInvoice(result.value, []);
  if (!issued.ok) throw new Error(`issueInvoice failed: ${issued.error}`);

  const summary = vatSummary([issued.value]);

  assert.ok(summary.length > 0);
  // Base: 2 * 9500 = 19000, then 10% discount = 19000 - 1900 = 17100
  const lineSubtotal = 2 * 9500;
  const expectedBase = lineSubtotal - Math.round(lineSubtotal * 10 / 100);
  assert.equal(summary[0].base, expectedBase);
});

test('vatSummary calculates VAT correctly', () => {
  const invoice = createIssuedInvoice('C-001', '2024-03-15', 1);
  const result = vatSummary([invoice]);

  assert.ok(result.length > 0);
  // VAT should be base * rate / 100
  // DEV-HOUR: 5000 * 20 / 100 = 1000
  const devHourEntry = result.find(e => e.rate === 20);
  if (devHourEntry) {
    assert.equal(devHourEntry.vat, Math.round(devHourEntry.base * 20 / 100));
  }
});

